#!/usr/bin/env node
/**
 * Extracts apps/mobile's local-snapshot type surface from
 * engine/src/snapshot.ts as a standalone .d.ts — the in-repo counterpart to
 * extract-public-types.mjs (hands#107). apps/mobile lives in this same
 * repo, so it vendors a generated file rather than importing engine/src
 * directly: that would pull the mobile app's TS compilation into engine's
 * module graph (Store, node:sqlite, server-only deps) for a client that
 * only needs 4 flat data interfaces, and a generated-and-regenerated .d.ts
 * is the pattern this repo already trusts (see extract-public-types.mjs).
 *
 * No renaming here (unlike extract-public-types.mjs) — MobileAgent/
 * MobileTask/MobileQuestion/MobileSnapshot are already named for their
 * audience in the source file.
 */
import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { extractClosure } from "./extract-interfaces.mjs";

const pkgDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const defaultSource = path.join(pkgDir, "src", "snapshot.ts");

export function extractMobileTypes(sourcePath = defaultSource) {
  // Derived closure from the one root (hands#217), not a hand-maintained
  // list — see extractClosure's docstring for why an enumerated list is the
  // failure mode this replaces.
  const blocks = extractClosure(sourcePath, ["MobileSnapshot"]);
  return `// generated by engine/scripts/extract-mobile-types.mjs from engine/src/snapshot.ts — do not edit by hand
// the local-only snapshot shape apps/mobile reads off a LAN "hands serve" instance's /api/events

${blocks.join("\n\n")}
`;
}

if (process.argv[1] && import.meta.url.endsWith(path.basename(process.argv[1]))) {
  const outPath = process.argv[2];
  const dts = extractMobileTypes();
  if (outPath) {
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, dts);
    process.stdout.write(`extracted → ${outPath}\n`);
  } else {
    process.stdout.write(dts);
  }
}
